// Parse Athena Page
//
// Input : one item = one raw Athena GetQueryResults response (one page, up to 1000 rows).
// Output: one item = { page, nextToken, rowCount, rows }, rows in Athena's own order.
//
// Runs once per page. Collect Export Rows reads every run of this node back by run index,
// so each run only has to describe its own page.

// 100 pages x 1000 rows. Far above what this export is expected to return; a result this
// large means a filter has gone missing, and one Sheets write would not carry it anyway.
const MAX_PAGES = 100;

// Athena column names, as aliased in the SQL. Sheet headers reuse them.
const COLUMNS = [
  'Brand',
  'User ID',
  'First name',
  'Phone Number',
  'Total Deposit',
  'Average Deposit',
  'Deposit Count',
  'LDD',
  'Hold %',
  'Player Status',
];

/** Athena returns every value as a string, or omits VarCharValue entirely for NULL. */
function cellValue(cell) {
  if (cell === null || cell === undefined) return null;
  const raw = cell.VarCharValue;
  if (raw === null || raw === undefined) return null;
  return String(raw);
}

const page = $runIndex;

if (page >= MAX_PAGES) {
  throw new Error(
    `Athena result exceeds ${MAX_PAGES} pages (${MAX_PAGES * 1000} rows). The export query ` +
      'has probably lost a filter — investigate before raising MAX_PAGES.',
  );
}

const inputItems = $input.all();
if (inputItems.length !== 1) {
  throw new Error(
    `Parse Athena Page expected exactly 1 input item from Athena, received ${inputItems.length}.`,
  );
}

const response = inputItems[0].json ?? {};
const resultSet = response.ResultSet;
if (!resultSet || !Array.isArray(resultSet.Rows)) {
  throw new Error(
    'Unexpected Athena response: ResultSet.Rows is missing. Check the Get Athena Results Page node output.',
  );
}

const columns = (resultSet.ResultSetMetadata?.ColumnInfo ?? []).map((column) => column?.Name);
const missingColumns = COLUMNS.filter((column) => !columns.includes(column));
if (missingColumns.length > 0) {
  throw new Error(
    `Athena result is missing column(s): ${missingColumns.join(', ')}. The export SQL and this ` +
      'node have drifted apart — update both together.',
  );
}

// Athena prepends a header row, on the first page only.
let rows = resultSet.Rows;
if (page === 0) {
  const firstRowValues = (rows[0]?.Data ?? []).map(cellValue);
  const firstRowIsHeader =
    firstRowValues.length === columns.length &&
    firstRowValues.every((value, index) => value === columns[index]);
  if (firstRowIsHeader) rows = rows.slice(1);
}

const records = [];
for (const row of rows) {
  const cells = row?.Data ?? [];
  const record = {};
  columns.forEach((columnName, index) => {
    record[columnName] = cellValue(cells[index]);
  });
  if (Object.values(record).every((value) => value === null)) continue;
  records.push(record);
}

return [
  {
    json: {
      page,
      nextToken: response.NextToken ?? null,
      rowCount: records.length,
      rows: records,
    },
  },
];

// Collect Export Rows
//
// Input : one item = the last page from Parse Athena Page ({ page, nextToken: null, ... }).
// Output: one item = { rowCount, records } — every Athena row, in query order.
//
// Gathers every run of Parse Athena Page in page order. Filtering and formatting happen
// later, in Build Sheet Payload, once the GR Base call history has been read.

const inputItems = $input.all();
if (inputItems.length !== 1) {
  throw new Error(`Collect Export Rows expected exactly 1 input item, received ${inputItems.length}.`);
}

const lastPage = inputItems[0].json.page;
if (!Number.isInteger(lastPage) || lastPage < 0) {
  throw new Error(`Collect Export Rows received an invalid page index: ${lastPage}.`);
}

const records = [];
for (let run = 0; run <= lastPage; run++) {
  const pageItems = $('Parse Athena Page').all(0, run);
  if (pageItems.length !== 1) {
    throw new Error(
      `Parse Athena Page run ${run} produced ${pageItems.length} items, expected 1. ` +
        'Pages cannot be stitched together reliably — no sheet was written.',
    );
  }
  records.push(...(pageItems[0].json.rows ?? []));
}

return [{ json: { rowCount: records.length, records } }];

// Select Recent Tabs
//
// Input : one item = the GR Base spreadsheet metadata from List Sheet Tabs ({ sheets: [{ properties: { title } }] }).
// Output: one item = { today, cooldownDays, tabs: [{ title, date, range }] } — the managers' date tabs
//         that fall inside the cooldown window.
//
// Managers name a calling-day tab by its date: 29/09, 2909, 30.09, 01.10, 9.07, "08.09 (таск)". A tab
// counts when its name STARTS with day+month; "Bonus", "task", "рассылка 24.06" do not. The year
// is the current one, unless that would put the tab in the future (a December tab read in January).

const config = $('Config').first().json;
const cooldownDays = Number(config.callCooldownDays);
if (!Number.isInteger(cooldownDays) || cooldownDays < 1) {
  throw new Error(`Config.callCooldownDays must be a whole number of days >= 1, got "${config.callCooldownDays}".`);
}

const inputItems = $input.all();
if (inputItems.length !== 1) {
  throw new Error(`Select Recent Tabs expected exactly 1 input item, received ${inputItems.length}.`);
}
const sheets = inputItems[0].json.sheets;
if (!Array.isArray(sheets)) {
  throw new Error('Unexpected Sheets response: "sheets" is missing. Check List Sheet Tabs.');
}

// Workflow timezone (Europe/Warsaw), midnight.
const today = $now.startOf('day');
// Window: the cooldownDays days BEFORE today. A player called on day D is skipped on D+1 .. D+cooldownDays
// (called yesterday -> skipped today, tomorrow and the day after, with the default of 3).
const windowStart = today.minus({ days: cooldownDays });
const windowEnd = today.minus({ days: 1 });

/** "29/09" / "2909" / "29.09" / "9.07" / "08.09 (таск)" -> a Luxon date, or null when the name is not a date. */
function tabDate(title) {
  const match = String(title).trim().match(/^(\d{1,2})[.\-\/]?(\d{2})(?!\d)/);
  if (!match) return null;
  const day = Number(match[1]);
  const month = Number(match[2]);
  if (day < 1 || day > 31 || month < 1 || month > 12) return null;
  let date = today.set({ year: today.year, month, day });
  if (!date.isValid || date.day !== day) return null; // e.g. 31.02
  if (date > today) date = date.minus({ years: 1 });
  return date;
}

const tabs = [];
for (const sheet of sheets) {
  const title = sheet?.properties?.title;
  if (typeof title !== 'string') continue;
  const date = tabDate(title);
  if (date === null || date < windowStart || date > windowEnd) continue;
  // A1 notation quotes a tab name in single quotes and doubles any quote inside it.
  tabs.push({ title, date: date.toISODate(), range: `'${title.replace(/'/g, "''")}'!A:Z` });
}

return [{ json: { today: today.toISODate(), cooldownDays, tabs } }];

// Build Sheet Payload
//
// Input : one item — either the batchGet response from Read Recent Tabs, or the Select Recent
//         Tabs item when no date tab fell inside the cooldown window (Recent Tabs Found? = false).
// Output: one item = { rowCount, excludedCount, range, clearRange, values } for the Sheets API calls.
//
// Drops every player whose User ID appears in a recent date tab, then turns the remaining
// records into the 2D array the sheet receives. Headers and column order are defined here and
// nowhere else. Written with valueInputOption=RAW: strings stay strings, so phone numbers keep
// their leading + or 0 and user ids are never reformatted as numbers.

// Column order in the sheet. `number` columns are sent as numbers so the sheet can sum and
// sort them; `text` columns as text; `blank` columns are left empty for the managers to fill.
const COLUMNS = [
  { key: 'Brand', header: 'Brand', type: 'text' },
  { key: 'User ID', header: 'User ID', type: 'text' },
  { key: 'First name', header: 'First name', type: 'text' },
  { key: 'Phone Number', header: 'Phone Number', type: 'text' },
  { key: 'Total Deposit', header: 'Total Deposit', type: 'number' },
  { key: 'Average Deposit', header: 'Average Deposit', type: 'number' },
  { key: 'Deposit Count', header: 'Deposit Count', type: 'number' },
  { key: 'LDD', header: 'LDD', type: 'number' },
  { key: 'Hold %', header: 'Hold %', type: 'number' },
  { key: 'Player Status', header: 'Player Status', type: 'text' },
  { header: 'Статус звонка', type: 'blank' },
  { header: 'Количество попыток дозвона', type: 'blank' },
  { header: 'Менеджер', type: 'blank' },
  { header: 'Комментарий', type: 'blank' },
];

// Header names managers have used for the player id column in the date tabs.
const ID_HEADERS = ['user id', 'userid', 'account', 'id'];

const LAST_COLUMN = String.fromCharCode('A'.charCodeAt(0) + COLUMNS.length - 1);

/** Same id whether it arrives as "123", 123 or "123.0" (Sheets turns ids into numbers). */
function normalizeId(raw) {
  if (raw === null || raw === undefined) return '';
  return String(raw).trim().replace(/\.0+$/, '');
}

/** NULL becomes an empty cell. Unparseable numbers also become empty, never NaN. */
function toCell(raw, type) {
  if (type === 'blank') return '';
  if (raw === null || raw === undefined) return '';
  const text = String(raw).trim();
  if (text === '') return '';
  if (type !== 'number') return text;
  const parsed = Number(text);
  return Number.isFinite(parsed) ? parsed : '';
}

const inputItems = $input.all();
if (inputItems.length !== 1) {
  throw new Error(`Build Sheet Payload expected exactly 1 input item, received ${inputItems.length}.`);
}

// --- Players already called inside the cooldown window -------------------------------------
const recentTabs = $('Select Recent Tabs').first().json.tabs ?? [];
const calledIds = new Set();
if (recentTabs.length > 0) {
  const valueRanges = inputItems[0].json.valueRanges;
  if (!Array.isArray(valueRanges)) {
    throw new Error('Unexpected Sheets response: "valueRanges" is missing. Check Read Recent Tabs.');
  }
  for (const valueRange of valueRanges) {
    const rows = valueRange.values ?? [];
    if (rows.length === 0) continue;
    const header = rows[0].map((cell) => String(cell ?? '').trim().toLowerCase());
    let idColumn = header.findIndex((name) => ID_HEADERS.includes(name));
    if (idColumn === -1) idColumn = 0;
    for (const row of rows.slice(1)) {
      const id = normalizeId(row[idColumn]);
      if (id !== '') calledIds.add(id);
    }
  }
}

// --- Filter and format ------------------------------------------------------------------------
const records = $('Collect Export Rows').first().json.records ?? [];
const kept = records.filter((record) => !calledIds.has(normalizeId(record['User ID'])));

const values = [COLUMNS.map((column) => column.header)];
for (const record of kept) {
  values.push(COLUMNS.map((column) => toCell(column.key ? record[column.key] : null, column.type)));
}

const tab = String($('Config').first().json.outputSheetTab ?? '').trim();
if (tab === '') {
  throw new Error('Config.outputSheetTab is empty. Set it to the name of the tab to overwrite.');
}
const quotedTab = `'${tab.replace(/'/g, "''")}'`;

return [
  {
    json: {
      rowCount: kept.length,
      excludedCount: records.length - kept.length,
      recentTabs: recentTabs.map((t) => t.title),
      range: `${quotedTab}!A1:${LAST_COLUMN}${values.length}`,
      // Cleared wider than the data, so columns left over from an earlier, wider layout go too.
      clearRange: `${quotedTab}!A:Z`,
      values,
    },
  },
];
